#include <windows.h>
#include <MagickCore/MagickCore.h>

void CaptureScreenContent() {
    HDC hdcScreen;
    HDC hdcMem;
    HBITMAP hBitmap;
    HBITMAP hOldBitmap;
    BITMAP bitmap;
    int x = 0, y = 0;
    int width = 0, height = 0;
    RECT rect;
    DISPLAY_DEVICE displayDevice;
    DWORD deviceCount = 0;
    Image *image = NULL;

    ZeroMemory(&displayDevice, sizeof(displayDevice));
    displayDevice.cb = sizeof(displayDevice);

    while (EnumDisplayDevices(NULL, deviceCount++, &displayDevice, 0)) {
        if (displayDevice.StateFlags & DISPLAY_DEVICE_ACTIVE) {
            hdcScreen = CreateDC("DISPLAY", displayDevice.DeviceName, NULL, NULL);
            if (!hdcScreen) {
                throw;
            }

            GetDeviceCaps(hdcScreen, &rect);
            width = rect.right;
            height = rect.bottom;

            hdcMem = CreateCompatibleDC(hdcScreen);
            if (!hdcMem) {
                DeleteDC(hdcScreen);
                throw;
            }

            hBitmap = CreateCompatibleBitmap(hdcScreen, width, height);
            if (!hBitmap) {
                DeleteDC(hdcMem);
                DeleteDC(hdcScreen);
                throw;
            }

            hOldBitmap = (HBITMAP)SelectObject(hdcMem, hBitmap);
            if (!hOldBitmap) {
                DeleteObject(hBitmap);
                DeleteDC(hdcMem);
                DeleteDC(hdcScreen);
                throw;
            }

            if (!BitBlt(hdcMem, 0, 0, width, height, hdcScreen, 0, 0, SRCCOPY)) {
                SelectObject(hdcMem, hOldBitmap);
                DeleteObject(hBitmap);
                DeleteDC(hdcMem);
                DeleteDC(hdcScreen);
                throw;
            }

            image = AcquireImage();
            if (!image) {
                SelectObject(hdcMem, hOldBitmap);
                DeleteObject(hBitmap);
                DeleteDC(hdcMem);
                DeleteDC(hdcScreen);
                throw;
            }

            image->columns = width;
            image->rows = height;

            if (!GetBitmapDimension(hdcMem, &width, &height, &bitmap)) {
                SelectObject(hdcMem, hOldBitmap);
                DeleteObject(hBitmap);
                DeleteDC(hdcMem);
                DeleteDC(hdcScreen);
                DestroyImage(image);
                throw;
            }

            MagickBool status;
            status = QueueAuthenticPixels(image, 0, 0, width, height, exception);
            if (!status) {
                SelectObject(hdcMem, hOldBitmap);
                DeleteObject(hBitmap);
                DeleteDC(hdcMem);
                DeleteDC(hdcScreen);
                DestroyImage(image);
                throw;
            }

            for (int i = 0; i < height; i++) {
                for (int j = 0; j < width; j++) {
                    COLORREF pixel = GetPixel(hdcMem, j, i);
                    unsigned int r = GetRValue(pixel);
                    unsigned int g = GetGValue(pixel);
                    unsigned int b = GetBValue(pixel);

                    SetPixelColor(image, j, i, r, g, b);
                }
            }

            status = SyncAuthenticPixels(image, exception);
            if (!status) {
                SelectObject(hdcMem, hOldBitmap);
                DeleteObject(hBitmap);
                DeleteDC(hdcMem);
                DeleteDC(hdcScreen);
                DestroyImage(image);
                throw;
            }

            SelectObject(hdcMem, hOldBitmap);
            DeleteObject(hBitmap);
            DeleteDC(hdcMem);
            DeleteDC(hdcScreen);
        }
    }
}

