#include <windows.h>
#include <wingdi.h>
#include <MagickCore/MagickCore.h>

void CaptureScreenToImage() {
    HDC hdcScreen;
    HBITMAP hBitmap;
    HDC hdcMem;
    BITMAP bitmap;
    int x = 0, y = 0;
    Image *image = NULL;

    // Initialize Magick
    (void) MagickCoreGenesis(NULL, MagickTrue);

    hdcScreen = GetDC(NULL);
    hdcMem = CreateCompatibleDC(hdcScreen);

    // Get screen dimensions
    int screenWidth = GetSystemMetrics(SM_CXSCREEN);
    int screenHeight = GetSystemMetrics(SM_CYSCREEN);

    // Create a compatible bitmap
    hBitmap = CreateCompatibleBitmap(hdcScreen, screenWidth, screenHeight);
    if (!hBitmap) {
        DestroyDC(hdcMem);
        ReleaseDC(NULL, hdcScreen);
        MagickCoreTerminus();
        throw Exception(3, "Failed to create compatible bitmap");
    }

    SelectObject(hdcMem, hBitmap);

    // Copy screen content to the compatible DC
    BitBlt(hdcMem, 0, 0, screenWidth, screenHeight, hdcScreen, 0, 0, SRCCOPY);

    // Create image from DC
    image = AcquireImage();
    image->columns = screenWidth;
    image->rows = screenHeight;
    image->depth = 8;

    GetObject(hBitmap, sizeof(bitmap), &bitmap);
    image->storage_class = DirectClass;
    image->colors = 0;
    image->matte = MagickFalse;

    // Allocate pixel buffer
    if (AcquireImagePixels(image, 0, 0, image->columns, image->rows, NULL) == (PixelPacket *) NULL) {
        DeleteObject(hBitmap);
        DestroyDC(hdcMem);
        ReleaseDC(NULL, hdcScreen);
        MagickCoreTerminus();
        throw Exception(3, "Failed to acquire image pixels");
    }

    // Copy pixel data from the bitmap to the image
    for (y = 0; y < screenHeight; y++) {
        for (x = 0; x < screenWidth; x++) {
            COLORREF color = GetPixel(hdcMem, x, y);
            int red = GetRValue(color);
            int green = GetGValue(color);
            int blue = GetBValue(color);

            SetPixelRed(image, ScaleCharToQuantum((unsigned char) red), image->pixels + y * image->columns + x);
            SetPixelGreen(image, ScaleCharToQuantum((unsigned char) green), image->pixels + y * image->columns + x);
            SetPixelBlue(image, ScaleCharToQuantum((unsigned char) blue), image->pixels + y * image->columns + x);
        }
    }

    // Update and synchronize the image pixels
    if (!QueueAuthenticPixels(image, 0, 0, image->columns, image->rows, NULL)) {
        DeleteObject(hBitmap);
        DestroyDC(hdcMem);
        ReleaseDC(NULL, hdcScreen);
        DestroyImage(image);
        MagickCoreTerminus();
        throw Exception(3, "Failed to queue authentic pixels");
    }

    if (!SyncAuthenticPixels(image, MagickTrue, NULL)) {
        DeleteObject(hBitmap);
        DestroyDC(hdcMem);
        ReleaseDC(NULL, hdcScreen);
        DestroyImage(image);
        MagickCoreTerminus();
        throw Exception(3, "Failed to synchronize authentic pixels");
    }

    // Cleanup
    DeleteObject(hBitmap);
    DestroyDC(hdcMem);
    ReleaseDC(NULL, hdcScreen);
    MagickCoreTerminus();
}
